class ListNode:
    def __init__(self, val=0, nxt=None):
        self.val = val
        self.next = nxt


def build_list(a: list) -> "ListNode":
    dummy = ListNode()          # dummy removes the "is it the head?" branch
    tail = dummy
    for x in a:
        tail.next = ListNode(x)
        tail = tail.next
    return dummy.next


def print_list(head) -> str:
    parts = []
    t = head
    while t:
        parts.append(str(t.val))
        t = t.next
    return " ".join(parts)

