ListNode* insertAtPosition(ListNode* head, int k, int val) {
    ListNode dummy(0); dummy.next = head;    // dummy makes the head case ordinary
    ListNode* prev = &dummy;
    for (int i = 1; i < k && prev->next; ++i) prev = prev->next;
    ListNode* node = new ListNode(val);
    node->next = prev->next;                 // FIRST: do not lose the tail
    prev->next = node;                       // THEN: splice it in
    return dummy.next;
}

ListNode* deleteAtPosition(ListNode* head, int k) {
    ListNode dummy(0); dummy.next = head;
    ListNode* prev = &dummy;
    for (int i = 1; i < k && prev->next; ++i) prev = prev->next;
    if (!prev->next) return dummy.next;      // k out of range: nothing to remove
    ListNode* target = prev->next;
    prev->next = target->next;               // bypass BEFORE freeing
    delete target;                           // C++ owns its memory
    return dummy.next;
}

ListNode* reverseList(ListNode* head) {
    ListNode *prev = nullptr, *cur = head;
    while (cur) {
        ListNode* ahead = cur->next;   // SAVE: the flip is about to destroy this
        cur->next = prev;              // FLIP
        prev = cur;                    // DOUBLE-STEP both pointers forward
        cur = ahead;
    }
    return prev;                       // cur is null; prev is the new head
}

long long sumOfNodes(ListNode* head) {
    long long sum = 0;                 // n=10^5 nodes at 10^9 each overflows int
    for (ListNode* t = head; t; t = t->next) sum += t->val;
    return sum;
}

void printReverse(ListNode* node, string& out) {
    if (!node) return;
    printReverse(node->next, out);     // go ALL the way to the tail first
    if (!out.empty()) out += ' ';
    out += to_string(node->val);       // print on the UNWIND: tail first
}

