struct DNode {
    int val; DNode *prev, *next;
    DNode(int v) : val(v), prev(nullptr), next(nullptr) {}
};

struct Deque {
    DNode *head = nullptr, *tail = nullptr;

    void pushFront(int v) {
        DNode* node = new DNode(v);
        if (!head) { head = tail = node; return; }   // empty: both ends are this node
        node->next = head;
        head->prev = node;                            // BOTH links, every time
        head = node;
    }
    void pushBack(int v) {
        DNode* node = new DNode(v);
        if (!tail) { head = tail = node; return; }
        node->prev = tail;
        tail->next = node;
        tail = node;
    }
    string forward() const {
        string out;
        for (DNode* t = head; t; t = t->next) { if (!out.empty()) out += ' '; out += to_string(t->val); }
        return out;
    }
    string backward() const {
        string out;
        for (DNode* t = tail; t; t = t->prev) { if (!out.empty()) out += ' '; out += to_string(t->val); }
        return out;
    }
};

