class DNode:
    def __init__(self, val=0):
        self.val = val
        self.prev = None
        self.next = None


class Deque:
    def __init__(self):
        self.head = None
        self.tail = None

    def push_front(self, v: int) -> None:
        node = DNode(v)
        if self.head is None:
            self.head = self.tail = node    # empty: both ends are this node
            return
        node.next = self.head
        self.head.prev = node               # BOTH links, every time
        self.head = node

    def push_back(self, v: int) -> None:
        node = DNode(v)
        if self.tail is None:
            self.head = self.tail = node
            return
        node.prev = self.tail
        self.tail.next = node
        self.tail = node

    def forward(self) -> str:
        out, t = [], self.head
        while t:
            out.append(str(t.val)); t = t.next
        return " ".join(out)

    def backward(self) -> str:
        out, t = [], self.tail
        while t:
            out.append(str(t.val)); t = t.prev
        return " ".join(out)
